function getEverlawTranslation(key, lang) {
    if (everlawTranslations[lang] && everlawTranslations[lang][key]) {
        return everlawTranslations[lang][key];
    }
    if (everlawTranslations.en && everlawTranslations.en[key]) {
        return everlawTranslations.en[key];
    }
    return null;
}

function applyEverlawTranslations(lang) {
    console.log('Applying everlaw translations for:', lang);
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.everlaw.')) {
            const translation = getEverlawTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    console.log(`Applied ${count} everlaw translations`);
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyEverlawTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyEverlawTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyEverlawTranslations(currentLang);
}

console.log('everlaw i18n loaded');
